'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const key='secureshop_agent_security',id='ss_inventory_cross_merchant_stock';
async function qualifyInventoryCatalog({origin,user,admin,password,root,label,seedDisplay}){
 const browser=await require('./secureshopAnalyticsBrowserOwner').launchOwnedAnalyticsBrowser(root,'inventorycatalog'),errors=[],blocked=[],screenshots=[];let page,adminPage;
 const api=(p,url,method='GET',body)=>p.evaluate(async({url,method,body})=>{const r=await fetch(url,{method,headers:{authorization:'Bearer '+localStorage.getItem('token'),'content-type':'application/json'},...(body===undefined?{}:{body:JSON.stringify(body)})});return{status:r.status,body:await r.json()};},{url,method,body});
 const click=async(p,selector)=>{const e=await p.waitForSelector(selector,{visible:true});await e.evaluate(x=>x.scrollIntoView({block:'center',behavior:'instant'}));await p.waitForFunction(s=>{const e=document.querySelector(s),r=e?.getBoundingClientRect(),h=r&&document.elementFromPoint(r.x+r.width/2,r.y+r.height/2);return e&&(h===e||e.contains(h));},{},selector);await e.click();};
 const button=async(p,label,scope='body')=>{const h=await p.evaluateHandle(({label,scope})=>[...document.querySelectorAll(scope+' button')].find(b=>b.textContent.trim()===label&&!b.disabled),{label,scope});assert.ok(h.asElement(),label);await h.asElement().evaluate(e=>e.scrollIntoView({block:'center',behavior:'instant'}));await h.asElement().click();};
 async function login(u){const c=await browser.createBrowserContext(),p=await c.newPage();await p.setViewport({width:1440,height:1100});await require('./fullBackendRenderedSecureShop').configurePage(p,origin,blocked,errors);await p.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await p.goto(origin+'/workshop-login');await p.waitForSelector('input[placeholder="Enter your username"]');await p.type('input[placeholder="Enter your username"]',u.username);await p.type('input[placeholder="Enter your password"]',password);await click(p,'button[type="submit"]');await p.waitForFunction(()=>localStorage.getItem('token')&&location.pathname!=='/workshop-login');return p;}
 const cardText=async p=>p.evaluate(()=>{const title=[...document.querySelectorAll('h3,.title')].find(e=>e.textContent.trim()==='SecureShop Agent Security');if(!title)return null;const card=title.parentElement.parentElement.parentElement;if(!card||card===document.body)return null;return card.innerText;});
 const count=async(p,n,total)=>p.waitForFunction(({n,total})=>{const title=[...document.querySelectorAll('h3,.title')].find(e=>e.textContent.trim()==='SecureShop Agent Security');const card=title?.parentElement.parentElement.parentElement;return card&&card!==document.body&&new RegExp(n+'\\s*/\\s*'+total+'|'+n+' of '+total).test(card.innerText);},{},{n,total});
 const screenshot=async(p,name)=>{await p.screenshot({path:path.join(root,name+'.png'),fullPage:true});screenshots.push(name+'.png');};
 const exercise=async()=>{await page.goto(origin+'/workshop/secureshop');await page.waitForSelector('section[aria-label="Exercise objectives"]');await page.waitForFunction(label=>document.querySelector('section[aria-label="Exercise objectives"]').textContent.includes(label),{},label);};
 const gateVisible=async(kind,value)=>{await page.waitForFunction(({kind,value})=>[...document.querySelectorAll('section[aria-label="Exercise objectives"] button')].some(b=>b.textContent.trim()===kind)===value,{},{kind,value});};
 try{
  page=await login(user);adminPage=await login(admin);
  await exercise();const metadata=await api(page,'/api/auth/secureshop-launch');assert.equal(metadata.status,200);assert.ok(metadata.body.launch);const projection=await seedDisplay({token:await page.evaluate(()=>localStorage.getItem('token')),launch:metadata.body.launch});
  for(const route of ['/workshop-dashboard','/workshop/challenges','/workshop/progress']){await page.goto(origin+route);await count(page,1,1);assert.ok((await cardText(page)).includes(route==='/workshop/challenges'?'< 1m':projection.timeSpentSeconds+'s'));if(route==='/workshop/progress')assert.equal(new URL(page.url()).pathname,'/workshop-dashboard');}
  const progress=await api(page,'/api/workshop/progress'),challenges=await api(page,'/api/workshop/challenges'),stats=await api(page,'/api/workshop/student/stats');const a=progress.body.challenges.find(x=>x.workshopKey===key),b=challenges.body.challenges.find(x=>x.workshopKey===key);assert.deepEqual(a,b);assert.equal(a.objectiveCount,1);assert.equal(a.completedObjectiveCount,1);assert.equal(stats.body.totalObjectives,1);assert.equal(stats.body.completedObjectives,1);await screenshot(page,'inventory-catalog-dashboard');
  await exercise();assert.ok((await page.$eval('section[aria-label="Exercise objectives"]',e=>e.textContent)).includes('Completed: '+label));
  for(const kind of ['hint','solution']){const endpoint=kind==='hint'?'/api/hints/'+key+'/'+id:'/api/solutions/secureshop-agent-security/'+id;const response=page.waitForResponse(r=>new URL(r.url()).pathname===endpoint);await button(page,kind==='hint'?'Hint':'Solution','section[aria-label="Exercise objectives"]');const r=await response;assert.equal(r.status(),200);const content=(await r.json())[kind];await page.waitForFunction(title=>document.querySelector('[role="dialog"]')?.textContent.includes(title),{},content.title);await click(page,'button[aria-label="Close '+kind+'"]');}
  await screenshot(page,'inventory-catalog-objective');
  await adminPage.goto(origin+'/admin/exercises');const card='[data-exercise-key="'+key+'"]';await adminPage.waitForSelector(card);await adminPage.$eval(card,e=>[...e.querySelectorAll('button')].find(b=>b.textContent.includes('Manage Objectives')).click());const row='[data-objective-id="'+id+'"]';await adminPage.waitForSelector(row);assert.ok(await adminPage.$(row+' [title="Preview Solution"]'));await screenshot(adminPage,'inventory-catalog-admin');
  const rowGate=async(h,s)=>adminPage.waitForFunction(({id,h,s})=>{const row=document.querySelector('[data-objective-id="'+id+'"]');if(!row)return false;const enabled=column=>getComputedStyle(row.children[column].firstElementChild).backgroundColor==='rgb(72, 187, 120)';return enabled(2)===h&&enabled(3)===s;},{},{id,h,s});
  const redirectedViews=[];
  const checkAdminAliases=async(h,s)=>{for(const alias of ['/admin/challenges','/admin/solutions']){await adminPage.goto(origin+alias);await adminPage.waitForFunction(()=>location.pathname==='/admin/exercises');await adminPage.waitForSelector(card);await adminPage.$eval(card,e=>[...e.querySelectorAll('button')].find(b=>b.textContent.includes('Manage Objectives')).click());await rowGate(h,s);redirectedViews.push({alias,resolved:'/admin/exercises',hint:h,solution:s});await screenshot(adminPage,'inventory-admin-'+alias.split('/').pop()+'-'+Number(h)+Number(s));}};
  // Exercise each actual objective toggle once in each direction; remaining
  // combinations use canonical API mutations and inspect both redirected views.
  await click(adminPage,row+' > div:nth-child(3) > div');await rowGate(false,true);await exercise();await gateVisible('Hint',false);await gateVisible('Solution',true);await click(adminPage,row+' > div:nth-child(3) > div');await rowGate(true,true);
  await click(adminPage,row+' > div:nth-child(4) > div');await rowGate(true,false);await exercise();await gateVisible('Hint',true);await gateVisible('Solution',false);await click(adminPage,row+' > div:nth-child(4) > div');await rowGate(true,true);
  for(const [h,s] of [[false,false],[true,false],[false,true],[true,true]]){const base='/api/admin/exercises/'+key+'/objectives/'+id;assert.equal((await api(adminPage,base+'/hint','PATCH',{enabled:h})).status,200);assert.equal((await api(adminPage,base+'/solution','PATCH',{enabled:s})).status,200);await exercise();await gateVisible('Hint',h);await gateVisible('Solution',s);assert.equal((await api(page,'/api/hints/'+key+'/'+id)).status,h?200:403);assert.equal((await api(page,'/api/solutions/secureshop-agent-security/'+id)).status,s?200:403);await checkAdminAliases(h,s);}
  // Real admin master controls must change only their own help dimension.
  await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="solutions"]');await exercise();await gateVisible('Solution',false);await gateVisible('Hint',true);await checkAdminAliases(true,false);await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="solutions"]');await click(adminPage,card+' [data-control="hints"]');await exercise();await gateVisible('Hint',false);await gateVisible('Solution',true);await checkAdminAliases(false,true);await adminPage.goto(origin+'/admin/exercises');await adminPage.waitForSelector(card);await click(adminPage,card+' [data-control="hints"]');
  assert.equal((await api(page,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:false})).status,403);assert.equal((await api(adminPage,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:false})).status,200);const hidden=await api(page,'/api/workshop/progress');const hiddenRow=hidden.body.challenges.find(x=>x.workshopKey===key);assert.equal(hiddenRow.objectiveCount,0);assert.equal(hiddenRow.completedObjectiveCount,0);assert.equal((await api(adminPage,'/api/admin/exercises/'+key+'/objectives/'+id,'PATCH',{enabled:true})).status,200);await page.goto(origin+'/workshop-dashboard');await count(page,1,1);
  await adminPage.goto(origin+'/admin/student-workshop-view?studentId='+user.id);await count(adminPage,1,1);assert.ok((await cardText(adminPage)).includes(projection.timeSpentSeconds+'s'));await screenshot(adminPage,'inventory-catalog-admin-student');
  await exercise();const reset=page.waitForResponse(r=>new URL(r.url()).pathname.endsWith('/reset')&&r.request().method()==='POST');await button(page,'Reset launch');assert.equal((await reset).status(),200);await page.goto(origin+'/workshop-dashboard');await count(page,0,1);assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);
  return{status:'passed',controlledDisplayOnly:true,displayScope:projection.displayScope,actualActorCalls:0,actualJudgeCalls:0,objectiveId:id,counts:{completed:1,total:1},nonzeroTime:projection.timeSpentSeconds,completedStyle:true,renderedObjectiveHelpCombinations:4,actualObjectiveHintAndSolutionToggles:true,adminRedirectProjections:redirectedViews,scopedCardCounts:true,independentMasterHelpControls:true,reset:true,screenshots};
 }catch(error){if(page)await screenshot(page,'inventory-catalog-failure').catch(()=>{});fs.writeFileSync(path.join(root,'inventory-catalog-error.json'),JSON.stringify({message:error.message,errors,blocked}),{mode:0o600});throw error;}finally{await browser.close();}
}
module.exports={qualifyInventoryCatalog};
